dropdown_dinamico_underscore.javascript:
const menuList = document.getElementById('mag-dynamic-menu');
if (menuList) {
  const items = Array.from(menuList.querySelectorAll('.mag-menu-item'));
  let currentParent = null;
  let currentDropdownMenu = null;

  items.forEach(item => {
    const link = item.querySelector('a');
    const text = link.textContent.trim();

    if (text.startsWith('_')) {
      link.textContent = text.substring(1).trim();
      link.classList.remove('nav-link');
      link.classList.add('dropdown-item');

      if (currentParent) {
        if (!currentDropdownMenu) {
          currentParent.classList.add('dropdown');
          const parentLink = currentParent.querySelector('a.nav-link');
          parentLink.classList.add('dropdown-toggle');
          parentLink.setAttribute('data-bs-toggle', 'dropdown');
          currentDropdownMenu = document.createElement('ul');
          currentDropdownMenu.className = 'dropdown-menu border-0';
          currentParent.appendChild(currentDropdownMenu);
        }
        item.classList.remove('nav-item');
        item.style.listStyle = 'none';
        currentDropdownMenu.appendChild(item);
      }
    } else {
      currentParent = item;
      currentDropdownMenu = null;
    }
  });
}

