back_to_top.javascript:
(function() {
  const btn = document.getElementById('btnVoltarTopo');
  if (!btn) return;

  window.addEventListener('scroll', function() {
    const y = window.scrollY || document.documentElement.scrollTop;
    if (y > 300) {
      btn.style.opacity = '1';
      btn.style.visibility = 'visible';
      btn.style.transform = 'translateY(0)';
    } else {
      btn.style.opacity = '0';
      btn.style.visibility = 'hidden';
      btn.style.transform = 'translateY(20px)';
    }
  });

  btn.addEventListener('click', () => window.scrollTo({ top: 0, behavior: 'smooth' }));
  btn.addEventListener('mouseover', () => { btn.style.transform = 'translateY(-5px) scale(1.1)'; });
  btn.addEventListener('mouseout', () => { if (window.scrollY > 300) btn.style.transform = 'translateY(0) scale(1)'; });
})();

page_list_active.javascript:
document.addEventListener('DOMContentLoaded', function() {
  const pageLinks = document.querySelectorAll('.PageList li a');
  const currentUrl = window.location.href.split(/[?#]/)[0];
  pageLinks.forEach(link => {
    if (link.href === currentUrl || (currentUrl.endsWith('/') && link.href.endsWith('/'))) {
      link.classList.add('active');
      link.parentElement.classList.add('selected');
    }
  });
});
